{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C38"],
      "claim": "Norethisterone, a 4-en-3-one steroid with a 17-substituent, has an absolute oral bioavailability of 64% in humans, supporting that the query's A-ring enone steroid core is generally well absorbed orally.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Levonorgestrel, a 4-en-3-one progestin, has a mean absolute oral bioavailability of 94% in humans, showing that 17-substituted A-ring enone steroids can achieve high oral F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Abiraterone has oral absolute bioavailability below 10% in humans, but its low F is tied to a 3-hydroxy-5,16-diene and pyridyl substitution, features not shared by the query's 4-en-3-one/methylsulfonylphenyl structure.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C56"],
      "claim": "Anecortave desacetate has low oral bioavailability in humans, but this reflects a metabolically labile corticosteroid side chain, unlike the query's fluorinated alcohol.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a 4-en-3-one steroid with a 17-hydroxy-fluorinated alkyl and an 11-aryl methylsulfone. Direct human absolute-bioavailability data for A-ring enone steroids (norethisterone, levonorgestrel, NOMAC, hydrocortisone) consistently show F well above 20%. The low-F analogues (abiraterone, anecortave) owe their poor F to specific metabolic/solubility liabilities absent in the query. Therefore, high oral bioavailability is better supported.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement for the exact query or a close analogue bearing both the 11-(4-methylsulfonylphenyl) and 17-fluorinated alcohol substituents.",
    "Lack of solubility, permeability, and first-pass metabolism data for this specific chemotype."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

